begin;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '',created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 2 and 200),business_type text not null, currency text not null default 'USD' check(currency in ('USD','CAD','GBP','EUR','AUD')),timezone text not null default 'America/Denver',contact_email text not null default '',address text not null default '',created_at timestamptz not null default now());
create table public.organization_memberships(organization_id uuid not null references public.organizations(id),user_id uuid not null references auth.users(id),role text not null default 'owner' check(role in ('owner','admin','worker')),primary key(organization_id,user_id));
create function public.is_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_memberships where organization_id=org and user_id=auth.uid())$$;
create function public.is_manager(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_memberships where organization_id=org and user_id=auth.uid() and role in ('owner','admin'))$$;
create table public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,email text not null default '',phone text not null default '',address text not null default '',notes text not null default '',archived boolean not null default false,created_at timestamptz not null default now(),unique(organization_id,id));
create table public.services(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,description text not null default '',default_cents bigint not null default 0 check(default_cents>=0),duration_minutes integer not null default 60 check(duration_minutes>0),labor_rate_cents bigint not null default 0 check(labor_rate_cents>=0),target_bps integer not null default 3500 check(target_bps>=0 and target_bps<10000),active boolean not null default true,unique(organization_id,id));
create table public.recurring_job_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),customer_id uuid not null,service_id uuid,description text not null,quoted_cents bigint not null check(quoted_cents>=0),labor_rate_cents bigint not null check(labor_rate_cents>=0),duration_minutes integer not null check(duration_minutes>0),interval text not null check(interval in ('weekly','biweekly','monthly')),next_date date not null,anchor_day integer not null check(anchor_day between 1 and 31),start_time time not null,active boolean not null default true,foreign key(organization_id,customer_id) references customers(organization_id,id),foreign key(organization_id,service_id) references services(organization_id,id),unique(organization_id,id));
create table public.jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),customer_id uuid not null,service_id uuid,description text not null,scheduled_date date not null,start_time time not null default '09:00',duration_minutes integer not null default 60 check(duration_minutes>0),actual_minutes integer not null default 0 check(actual_minutes>=0),labor_rate_cents bigint not null default 0 check(labor_rate_cents>=0),quoted_cents bigint not null check(quoted_cents>=0),final_cents bigint check(final_cents>=0),status text not null default 'scheduled' check(status in ('draft','scheduled','in_progress','completed','canceled')),notes text not null default '',completed_at timestamptz,created_at timestamptz not null default now(),recurring_rule_id uuid,unique(organization_id,id),unique(recurring_rule_id,scheduled_date),foreign key(organization_id,customer_id) references customers(organization_id,id),foreign key(organization_id,service_id) references services(organization_id,id),foreign key(organization_id,recurring_rule_id) references recurring_job_rules(organization_id,id));
create table public.expenses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),job_id uuid,vendor text not null,description text not null default '',category text not null check(category in ('fuel','equipment','maintenance','materials','labor','vehicle','insurance','software','advertising','supplies','other')),amount_cents bigint not null check(amount_cents>0),expense_date date not null,created_at timestamptz not null default now(),foreign key(organization_id,job_id) references jobs(organization_id,id));
create table public.time_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),job_id uuid not null,minutes integer not null check(minutes>0),hourly_cents bigint not null check(hourly_cents>=0),created_at timestamptz not null default now(),foreign key(organization_id,job_id) references jobs(organization_id,id));
create table public.estimates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),customer_id uuid not null,description text not null,status text not null default 'draft' check(status in ('draft','accepted','expired')),expires_date date not null,notes text not null default '',converted_job_id uuid,created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,customer_id) references customers(organization_id,id),foreign key(organization_id,converted_job_id) references jobs(organization_id,id));
create table public.estimate_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,estimate_id uuid not null,description text not null,quantity_milli integer not null check(quantity_milli>0),unit_cents bigint not null check(unit_cents>=0),foreign key(organization_id,estimate_id) references estimates(organization_id,id));
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),customer_id uuid not null,job_id uuid,number integer not null,customer_name text not null,customer_email text not null default '',customer_address text not null default '',tax_bps integer not null default 0 check(tax_bps between 0 and 10000),status text not null default 'draft' check(status in ('draft','sent','voided')),due_date date not null,notes text not null default '',created_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,number),unique(organization_id,job_id),foreign key(organization_id,customer_id) references customers(organization_id,id),foreign key(organization_id,job_id) references jobs(organization_id,id));
create table public.invoice_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,invoice_id uuid not null,description text not null,quantity_milli integer not null check(quantity_milli>0),unit_cents bigint not null check(unit_cents>=0),foreign key(organization_id,invoice_id) references invoices(organization_id,id));
create table public.payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,invoice_id uuid not null,amount_cents bigint not null check(amount_cents>0),payment_date date not null,reference text not null default '',request_id uuid not null unique,created_at timestamptz not null default now(),foreign key(organization_id,invoice_id) references invoices(organization_id,id));
create table public.subscriptions(organization_id uuid primary key references organizations(id),stripe_customer_id text unique,stripe_subscription_id text unique,status text not null default 'inactive',price_id text,period_end timestamptz,verified_at timestamptz);
create table public.billing_events(event_id text primary key,created_at timestamptz not null default now());
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),actor_id uuid,event text not null,record_id uuid,created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,window_start timestamptz not null,hits integer not null);
create function public.has_pro(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from subscriptions where organization_id=org and status in ('active','trialing') and period_end>now() and verified_at is not null)$$;
create function public.guard_customer_limit() returns trigger language plpgsql security definer set search_path=public as $$begin perform pg_advisory_xact_lock(hashtextextended(new.organization_id::text,0));if not new.archived and not has_pro(new.organization_id) and (select count(*) from customers where organization_id=new.organization_id and not archived and id<>new.id)>=10 then raise exception 'Starter supports 10 active customers. Upgrade to add more.';end if;return new;end$$;
create trigger customer_limit before insert or update on customers for each row execute function guard_customer_limit();
create function public.guard_job() returns trigger language plpgsql set search_path=public as $$begin if old.status in ('completed','canceled') then raise exception 'Completed or canceled jobs are historical records';end if;if old.status<>new.status and not ((old.status='draft' and new.status in ('scheduled','canceled')) or (old.status='scheduled' and new.status in ('in_progress','canceled')) or (old.status='in_progress' and new.status in ('completed','canceled'))) then raise exception 'Invalid job status transition';end if;if new.status='completed' then new.completed_at=now();new.final_cents=coalesce(new.final_cents,new.quoted_cents);end if;return new;end$$;
create trigger job_lifecycle before update on jobs for each row execute function guard_job();
create function public.create_organization(p_name text,p_type text,p_timezone text,p_currency text) returns uuid language plpgsql security definer set search_path=public as $$declare org uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,1));if exists(select 1 from organization_memberships where user_id=auth.uid()) then raise exception 'Business already exists';end if;if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'Invalid timezone';end if;insert into profiles(id) values(auth.uid()) on conflict do nothing;insert into organizations(name,business_type,timezone,currency) values(p_name,p_type,p_timezone,p_currency) returning id into org;insert into organization_memberships values(org,auth.uid(),'owner');return org;end$$;
create function public.invoice_total(invoice uuid) returns bigint language sql stable set search_path=public as $$with s as(select coalesce(sum(round(quantity_milli::numeric*unit_cents/1000)),0) subtotal from invoice_items where invoice_id=invoice) select (subtotal+round(subtotal*i.tax_bps/10000))::bigint from s,invoices i where i.id=invoice$$;
create function public.create_invoice(p_org uuid,p_customer uuid,p_job uuid,p_description text,p_unit_cents bigint,p_quantity integer,p_tax integer,p_due date,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$declare inv uuid;c customers;j jobs;num integer;begin if not is_manager(p_org) or not has_pro(p_org) then raise exception 'Pro plan and manager permissions required';end if;perform 1 from organizations where id=p_org for update;select * into strict c from customers where id=p_customer and organization_id=p_org;if p_job is not null then select * into strict j from jobs where id=p_job and organization_id=p_org and customer_id=p_customer and status='completed';if p_unit_cents<>j.final_cents or p_quantity<>1000 then raise exception 'Job invoice must use completed job charge';end if;end if;select coalesce(max(number),0)+1 into num from invoices where organization_id=p_org;insert into invoices(organization_id,customer_id,job_id,number,customer_name,customer_email,customer_address,tax_bps,due_date,notes) values(p_org,p_customer,p_job,num,c.name,c.email,c.address,p_tax,p_due,p_notes) returning id into inv;insert into invoice_items(organization_id,invoice_id,description,quantity_milli,unit_cents) values(p_org,inv,p_description,p_quantity,p_unit_cents);insert into audit_events(organization_id,actor_id,event,record_id) values(p_org,auth.uid(),'invoice.created',inv);return inv;end$$;
create function public.record_payment(p_invoice uuid,p_amount bigint,p_date date,p_reference text,p_request uuid) returns uuid language plpgsql security definer set search_path=public as $$declare inv invoices;paid bigint;result uuid;begin select * into strict inv from invoices where id=p_invoice for update;if not is_manager(inv.organization_id) or not has_pro(inv.organization_id) then raise exception 'Pro plan and manager permissions required';end if;if exists(select 1 from payments where request_id=p_request) then select id into result from payments where request_id=p_request and invoice_id=p_invoice;if result is null then raise exception 'Request already used';end if;return result;end if;if inv.status='voided' then raise exception 'Cannot pay a void invoice';end if;select coalesce(sum(amount_cents),0) into paid from payments where invoice_id=p_invoice;if p_amount<=0 or paid+p_amount>invoice_total(p_invoice) then raise exception 'Payment exceeds outstanding balance or is invalid';end if;insert into payments(organization_id,invoice_id,amount_cents,payment_date,reference,request_id) values(inv.organization_id,p_invoice,p_amount,p_date,p_reference,p_request) returning id into result;update invoices set status='sent' where id=p_invoice;insert into audit_events(organization_id,actor_id,event,record_id) values(inv.organization_id,auth.uid(),'payment.recorded',result);return result;end$$;
create function public.create_estimate(p_org uuid,p_customer uuid,p_description text,p_amount bigint,p_expires date,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;begin if not is_manager(p_org) or not has_pro(p_org) then raise exception 'Pro plan and manager permissions required';end if;insert into estimates(organization_id,customer_id,description,expires_date,notes) values(p_org,p_customer,p_description,p_expires,p_notes) returning id into result;insert into estimate_items(organization_id,estimate_id,description,quantity_milli,unit_cents) values(p_org,result,p_description,1000,p_amount);return result;end$$;
create function public.convert_estimate(p_estimate uuid,p_date date,p_time time) returns uuid language plpgsql security definer set search_path=public as $$declare e estimates;result uuid;total bigint;begin select * into strict e from estimates where id=p_estimate for update;if not is_manager(e.organization_id) or not has_pro(e.organization_id) then raise exception 'Pro plan and manager permissions required';end if;if e.converted_job_id is not null then return e.converted_job_id;end if;if e.expires_date<(now() at time zone (select timezone from organizations where id=e.organization_id))::date then raise exception 'Estimate has expired';end if;select sum(round(quantity_milli::numeric*unit_cents/1000)) into total from estimate_items where estimate_id=e.id;insert into jobs(organization_id,customer_id,description,scheduled_date,start_time,quoted_cents,notes) values(e.organization_id,e.customer_id,e.description,p_date,p_time,total,e.notes) returning id into result;update estimates set status='accepted',converted_job_id=result where id=e.id;return result;end$$;
create function public.limit_request(p_key text,p_limit integer,p_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$declare n integer;begin insert into rate_limits(key,window_start,hits) values(p_key,now(),1) on conflict(key) do update set hits=case when rate_limits.window_start<now()-make_interval(secs=>p_seconds) then 1 else rate_limits.hits+1 end,window_start=case when rate_limits.window_start<now()-make_interval(secs=>p_seconds) then now() else rate_limits.window_start end returning hits into n;return n<=p_limit;end$$;
-- RLS: client cannot grant memberships, alter subscriptions, or mutate payments.
alter table profiles enable row level security;
create policy own_profile on profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table organizations enable row level security;
create policy org_read on organizations for select to authenticated using(is_member(id));
create policy org_update on organizations for update to authenticated using(is_manager(id)) with check(is_manager(id));
alter table organization_memberships enable row level security;
create policy membership_read on organization_memberships for select to authenticated using(user_id=auth.uid());
do $$declare t text;begin foreach t in array array['customers','services','jobs','expenses','time_entries','recurring_job_rules'] loop execute format('alter table %I enable row level security',t);execute format('create policy tenant_read on %I for select to authenticated using(is_member(organization_id))',t);execute format('create policy tenant_insert on %I for insert to authenticated with check(is_manager(organization_id))',t);execute format('create policy tenant_update on %I for update to authenticated using(is_manager(organization_id)) with check(is_manager(organization_id))',t);execute format('create index on %I(organization_id)',t);end loop;end$$;
-- Only verified Pro subscribers may write recurring rules.
drop policy tenant_insert on recurring_job_rules;drop policy tenant_update on recurring_job_rules;
create policy recurring_insert on recurring_job_rules for insert to authenticated with check(is_manager(organization_id) and has_pro(organization_id));
create policy recurring_update on recurring_job_rules for update to authenticated using(is_manager(organization_id) and has_pro(organization_id)) with check(is_manager(organization_id) and has_pro(organization_id));
do $$declare t text;begin foreach t in array array['estimates','estimate_items','invoices','invoice_items','payments','subscriptions','audit_events'] loop execute format('alter table %I enable row level security',t);execute format('create policy tenant_read on %I for select to authenticated using(is_manager(organization_id))',t);end loop;end$$;
alter table billing_events enable row level security;alter table rate_limits enable row level security;
create index on jobs(organization_id,scheduled_date);create index on expenses(organization_id,expense_date);create index on payments(organization_id,payment_date);create index on invoices(organization_id,due_date);
-- Default execute privileges are broad; explicitly restrict privileged helpers.
revoke all on function limit_request(text,integer,integer) from public,anon,authenticated;
grant execute on function limit_request(text,integer,integer) to service_role;
revoke all on function create_organization(text,text,text,text),create_invoice(uuid,uuid,uuid,text,bigint,integer,integer,date,text),record_payment(uuid,bigint,date,text,uuid),create_estimate(uuid,uuid,text,bigint,date,text),convert_estimate(uuid,date,time) from public,anon;
grant execute on function create_organization(text,text,text,text),create_invoice(uuid,uuid,uuid,text,bigint,integer,integer,date,text),record_payment(uuid,bigint,date,text,uuid),create_estimate(uuid,uuid,text,bigint,date,text),convert_estimate(uuid,date,time) to authenticated;
-- Transactional recurring setup; occurrences are unique per rule and local date.
create function public.make_recurring(p_job uuid,p_interval text) returns uuid language plpgsql security definer set search_path=public as $$declare j jobs;r uuid;begin select * into strict j from jobs where id=p_job for update;if not is_manager(j.organization_id) or not has_pro(j.organization_id) then raise exception 'Pro plan and manager permissions required';end if;if p_interval not in ('weekly','biweekly','monthly') then raise exception 'Invalid interval';end if;if j.recurring_rule_id is not null then return j.recurring_rule_id;end if;insert into recurring_job_rules(organization_id,customer_id,service_id,description,quoted_cents,labor_rate_cents,duration_minutes,interval,next_date,anchor_day,start_time) values(j.organization_id,j.customer_id,j.service_id,j.description,j.quoted_cents,j.labor_rate_cents,j.duration_minutes,p_interval,j.scheduled_date,extract(day from j.scheduled_date),j.start_time) returning id into r;update jobs set recurring_rule_id=r where id=j.id;return r;end$$;
revoke all on function make_recurring(uuid,text) from public,anon;grant execute on function make_recurring(uuid,text) to authenticated;
create function public.generate_recurring(p_until date) returns integer language plpgsql security definer set search_path=public as $$declare r recurring_job_rules;day date;following date;n integer:=0;begin if p_until>current_date+90 then raise exception 'Maximum horizon 90 days';end if;for r in select * from recurring_job_rules where active and has_pro(organization_id) for update skip locked loop day:=r.next_date;while day<=p_until loop insert into jobs(organization_id,customer_id,service_id,description,scheduled_date,start_time,duration_minutes,labor_rate_cents,quoted_cents,recurring_rule_id) values(r.organization_id,r.customer_id,r.service_id,r.description,day,r.start_time,r.duration_minutes,r.labor_rate_cents,r.quoted_cents,r.id) on conflict(recurring_rule_id,scheduled_date) do nothing;if found then n:=n+1;end if;if r.interval='monthly' then following:=(date_trunc('month',day)+interval '1 month')::date;day:=following+least(r.anchor_day-1,extract(day from (following+interval '1 month -1 day'))::integer-1);else day:=day+case when r.interval='weekly' then 7 else 14 end;end if;end loop;update recurring_job_rules set next_date=day where id=r.id;end loop;return n;end$$;
revoke all on function generate_recurring(date) from public,anon,authenticated;grant execute on function generate_recurring(date) to service_role;
create function public.set_invoice_status(p_invoice uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$declare inv invoices;begin select * into strict inv from invoices where id=p_invoice for update;if not is_manager(inv.organization_id) or not has_pro(inv.organization_id) then raise exception 'Pro plan and manager permissions required';end if;if p_status not in ('sent','voided') or inv.status='voided' then raise exception 'Invalid invoice transition';end if;if p_status='voided' and exists(select 1 from payments where invoice_id=inv.id) then raise exception 'An invoice with payments cannot be voided';end if;update invoices set status=p_status where id=inv.id;insert into audit_events(organization_id,actor_id,event,record_id) values(inv.organization_id,auth.uid(),'invoice.'||p_status,inv.id);end$$;
revoke all on function set_invoice_status(uuid,text) from public,anon;grant execute on function set_invoice_status(uuid,text) to authenticated;
alter table subscriptions add column last_event_created bigint not null default 0;
create function public.apply_billing_event(p_event text,p_created bigint,p_org uuid,p_customer text,p_subscription text,p_status text,p_price text,p_end timestamptz) returns void language plpgsql security definer set search_path=public as $$begin perform 1 from subscriptions where organization_id=p_org and stripe_customer_id=p_customer for update;if not found then raise exception 'Customer mapping missing';end if;insert into billing_events(event_id) values(p_event) on conflict do nothing;if not found then return;end if;update subscriptions set stripe_subscription_id=p_subscription,status=p_status,price_id=p_price,period_end=p_end,verified_at=now(),last_event_created=p_created where organization_id=p_org and stripe_customer_id=p_customer and last_event_created<=p_created;end$$;
revoke all on function apply_billing_event(text,bigint,uuid,text,text,text,text,timestamptz) from public,anon,authenticated;grant execute on function apply_billing_event(text,bigint,uuid,text,text,text,text,timestamptz) to service_role;
-- Enforce invariants at the database boundary, including direct API clients.
create function public.guard_job_insert() returns trigger language plpgsql set search_path=public as $$begin if new.status not in ('draft','scheduled') or new.final_cents is not null or new.completed_at is not null or new.actual_minutes<>0 then raise exception 'New jobs must begin as drafts or scheduled jobs';end if;return new;end$$;
create trigger job_insert_guard before insert on jobs for each row execute function guard_job_insert();
create function public.guard_organization_settings() returns trigger language plpgsql set search_path=public as $$begin if not exists(select 1 from pg_timezone_names where name=new.timezone) then raise exception 'Invalid timezone';end if;if old.currency<>new.currency and (exists(select 1 from jobs where organization_id=old.id) or exists(select 1 from expenses where organization_id=old.id) or exists(select 1 from invoices where organization_id=old.id) or exists(select 1 from estimates where organization_id=old.id)) then raise exception 'Currency is locked after financial records exist';end if;return new;end$$;
create trigger organization_settings_guard before update on organizations for each row execute function guard_organization_settings();
alter table audit_events add column details jsonb not null default '{}';
create function public.audit_business_mutation() returns trigger language plpgsql security definer set search_path=public as $$begin insert into audit_events(organization_id,actor_id,event,record_id,details) values(new.organization_id,auth.uid(),tg_table_name||'.'||lower(tg_op),new.id,case when tg_op='UPDATE' then jsonb_build_object('old_amount_cents',to_jsonb(old)->'amount_cents','new_amount_cents',to_jsonb(new)->'amount_cents','old_status',to_jsonb(old)->'status','new_status',to_jsonb(new)->'status') else '{}'::jsonb end);return new;end$$;
create trigger audit_jobs after insert or update on jobs for each row execute function audit_business_mutation();
create trigger audit_expenses after insert or update on expenses for each row execute function audit_business_mutation();
-- Monetary values must remain safely representable in the TypeScript application.
alter table jobs add check(quoted_cents<=1000000000000 and final_cents<=1000000000000 and labor_rate_cents<=100000000);
alter table expenses add check(amount_cents<=1000000000000);
alter table invoice_items add check(unit_cents<=1000000000000 and quantity_milli<=1000000);
alter table estimate_items add check(unit_cents<=1000000000000 and quantity_milli<=1000000);
alter table payments add check(amount_cents<=1000000000000);

-- Explicit privileges complement RLS and do not depend on project defaults.
do $$declare t text;begin foreach t in array array['profiles','organizations','organization_memberships','customers','services','jobs','expenses','time_entries','recurring_job_rules','estimates','estimate_items','invoices','invoice_items','payments','subscriptions','audit_events','billing_events','rate_limits'] loop execute format('revoke all on table %I from anon,authenticated',t);execute format('grant all on table %I to service_role',t);end loop;end$$;
grant usage on schema public to authenticated,service_role;
grant select,insert,update on profiles,customers,services,jobs,expenses,time_entries,recurring_job_rules to authenticated;
grant select,update on organizations to authenticated;
grant select on organization_memberships,estimates,estimate_items,invoices,invoice_items,payments,subscriptions,audit_events to authenticated;
commit;
